'use strict';
const $ = selector => document.querySelector(selector);
const state = {language:localStorage.getItem('rihlati-language')||'ar',view:'chat',adminTab:'overview',data:null,office:null,busy:false,draft:'',search:[],searchQuery:'',evaluation:null,correction:null,recording:false,audio:null,audioUrl:null,reader:null,recordStream:null};
const tr = (ar,en) => state.language === 'ar' ? ar : (TRANSLATIONS[state.language]?.[en] || en);
const esc = (text='') => String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const subject = key => ({tawhid:tr('التوحيد','Tawhid'),fiqh:tr('الفقه','Fiqh'),hadith:tr('الحديث','Hadith'),sirah:tr('السيرة','Seerah'),general:tr('عام','General')})[key]||key;
const btn=(label,action,value='',cls='secondary')=>`<button type="button" class="${cls}" data-action="${action}" data-value="${esc(value)}">${label}</button>`;
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-9.5A8.5 8.5 0 0 1 10.5 4H21z"/><path d="M7 9h9M7 14h6"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',sound:'<path d="m11 5-6 4H2v6h3l6 4zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1v15"/>',arrow:'<path d="M12 19V5m-6 6 6-6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',person:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 6 6"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>'})[name]||''}</svg>`;
async function api(path,payload,extra={}) {
  const options={...extra,credentials:'same-origin',headers:{'X-Rihlati-Client':'web','X-CSRF-Token':state.csrf||'',...(extra.headers||{})}};
  if(payload!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.body=JSON.stringify(payload);}
  const epoch=state.authEpoch||0;const response=await fetch(path,options);
  const data=await response.json();if(epoch!==(state.authEpoch||0))throw new Error('Session changed. Please retry.');
  if(response.status===401){resetPrivateState();render();}
  if(data.csrf)state.csrf=data.csrf;
  if(!response.ok){const error=new Error(data.error||tr('تعذر إكمال الطلب.','Request failed.'));error.code=data.code;error.reviewPage=data.review_page;throw error;}
  return data;
}
function toast(text){const element=$('#toast');element.textContent=text;element.hidden=false;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>element.hidden=true,6500);}
async function load(){await loadTranslations();await authSession();if(!accountReady()){state.data=null;return;}state.data=await api('/api/bootstrap?language='+state.language);if(state.view==='admin'){if(!adminTabAllowed(state.adminTab))state.adminTab='overview';state.office=await api('/api/dashboard');if(state.adminTab==='accounts')state.accounts=await api('/api/admin/accounts');if(state.adminTab==='staff')state.staff=await api('/api/office/staff');}}
function date(text){return new Date(text).toLocaleString(({ar:'ar-SA',en:'en-GB',fil:'fil-PH',fr:'fr-FR',am:'am-ET',sw:'sw-KE'})[state.language],{dateStyle:'short',timeStyle:'short'});}
function title(ar,en,sub=''){return `<div class="page-title"><div><span class="eyebrow">${tr('رِحلتي · فريق سراج','RIHLATI · SIRAJ')}</span><h1>${tr(ar,en)}</h1>${sub?`<p>${sub}</p>`:''}</div>${btn(icon('chat')+tr('مساعد رِحلتي','Rihlati assistant'),'view','chat')}</div>`;}
function modeLabel(mode){return ({ai:tr('جواب المساعد من الإدارةة','AI answer from the library'),library_excerpt:tr('مقتطف من الإدارةة','Library excerpt'),reviewed_answer:tr('إجابة معتمدة من المختص','Reviewed specialist answer'),specialist:tr('رد المختص','Specialist reply'),escalation:tr('إحالة إلى المختص','Specialist referral'),conversation:tr('مساعد رِحلتي','Rihlati assistant')})[mode]||mode;}
function citations(list=[]){return list.map(c=>`<div class="citation">${icon('book')}<div>${c.pdf_url?`<a href="${esc(c.pdf_url)}" target="_blank" rel="noopener">${esc(c.title)} · ${tr('ص','p.')} ${c.page_number}</a>`:`<strong>${esc(c.title)}</strong>`}${c.source_note?`<small>${esc(c.source_note)}</small>`:''}${c.extraction_status==='ocr'?`<small>${tr('نص مستخرج من صفحة مصوّرة؛ يمكنك مراجعة الأصل.','Text extracted from a scanned page; the original is available.')}</small>`:''}</div></div>`).join('');}
function learnerNav(){return `<nav class="subnav" aria-label="${tr('أقسام المستفيد','Learner sections')}">${[['chat',tr('مساعد رِحلتي','Assistant')],['journey',tr('مساري التعليمي','Learning path')],['faq',tr('الأسئلة الشائعة','Common questions')],['tickets',tr('تذاكري','My tickets')]].map(([value,label])=>btn(label,'view',value,state.view===value?'subnav-active':'subnav-btn')).join('')}</nav>`;}
function chatPage(){
  const messages=state.data.messages||[];
  const greeting=tr('أهلًا بك، أنا مساعد رِحلتي.','Welcome. I am your Rihlati assistant.');
  const intro=tr('ما الذي يشغلك اليوم؟ اسألني عن رحلتك في تعلّم الإسلام، وسأبحث لك في المراجع، ويمكنني ربطك بالمختص متى رغبت.','What is on your mind? Ask about your journey in learning Islam. I will search the library and connect you with a specialist whenever you wish.');
  return `<div class="chat-layout"><section class="chat-panel"><header class="chat-heading"><div class="assistant-avatar"><img src="logo-rihlati.svg" alt=""/></div><div><h1>${tr('مساعد رِحلتي','Rihlati assistant')}</h1><p><span class="online-dot"></span>${state.data.ai.configured?tr('المكتبة والمختص معك','Your library and specialist, together'):tr('المكتبة متاحة · تفعيل الذكاء الاصطناعي من الإدارة','Library available · activate AI in administrator settings')}</p></div>${btn(icon('person')+tr('المختص','Specialist'),'new-ticket','','quiet')}</header>
  <div class="messages" id="messages" role="log" aria-live="polite" aria-label="${tr('المحادثة','Conversation')}"><article class="message assistant welcome"><span class="message-name">${tr('مساعد رِحلتي','Rihlati assistant')}</span><h2>${greeting}</h2><p>${intro}</p><div class="quick-prompts">${[tr('ما معنى التوحيد؟','What is tawhid?'),tr('كيف أتعلم الوضوء؟','How do I perform wudu?'),tr('حدثني عن حسن الخلق','Tell me about good character')].map(q=>btn(esc(q),'ask',q,'prompt-chip')).join('')}</div></article>${messages.map(m=>`<article class="message ${m.role==='user'?'user':'assistant'}"><span class="message-name">${m.role==='user'?tr('أنت','You'):modeLabel(m.mode)}</span><p class="message-text" dir="auto">${esc(m.content)}</p>${citations(m.citations)}${m.ticket_id?`<div class="ticket-notice">${tr('تذكرة المختص','Specialist ticket')} #${m.ticket_id} ${btn(tr('متابعة','Track'),'view','tickets','text-link')}</div>`:''}<div class="message-actions">${btn(icon('sound')+tr('استماع','Listen'),'speak',m.id,'quiet')}${m.role!=='user'&&m.question&&!m.ticket_id?btn(tr('تحدث إلى المختص','Ask a specialist'),'escalate',m.id,'quiet'):''}</div><div class="audio-target" data-audio-id="${m.id}"></div></article>`).join('')}${state.busy?`<div class="thinking" role="status"><i></i><i></i><i></i>${tr('أبحث في مكتبتك…','Searching your library…')}</div>`:''}</div>
  <form id="chat-form" class="composer"><label class="sr-only" for="question">${tr('سؤالك','Your question')}</label><textarea id="question" name="question" maxlength="2000" rows="2" placeholder="${tr('اكتب سؤالك… أو سجّله بصوتك','Type your question… or record it')}" ${state.busy?'disabled':''}>${esc(state.draft)}</textarea><div class="composer-actions"><div class="voice-actions">${btn(icon(state.recording?'stop':'mic')+tr(state.recording?'إنهاء التسجيل':'سؤال صوتي',state.recording?'Stop recording':'Record question'),'record','','quiet '+(state.recording?'recording':''))}${btn(tr('رفع تسجيل','Upload audio'),'audio-file','','quiet')}</div><button class="send" type="submit" aria-label="${tr('إرسال السؤال','Send question')}" ${state.busy?'disabled':''}>${icon('arrow')}</button></div><p class="composer-note">${state.data.ai.audio_configured?tr('صوت مولّد بالذكاء الاصطناعي. يمكنك مراجعة السؤال بعد تفريغه وقبل إرساله.','AI-generated voice. Review the transcript before sending.'):tr('الصوت المحلي بحسب المتصفح؛ الصوت المحسّن يحتاج تفعيل الخدمة من الإدارة.','Local voice depends on your browser; enhanced voice requires activation.')}</p></form><input id="audio-file" type="file" accept="audio/*,video/mp4" hidden></section>
  <aside class="chat-aside"><div class="path-preview"><span class="eyebrow">${tr('خطوتك القادمة','YOUR NEXT STEP')}</span><h2>${tr('كل سؤال، خطوة للأمام','Every question, a step forward')}</h2><p>${tr('تعلّم على ثلاثة مستويات، واحتفظ بتقدمك بين الزيارات.','Learn through three levels and keep your progress between visits.')}</p><div class="progress-line"><i style="width:${state.data.learner.progress}%"></i></div><small>${state.data.learner.progress}% ${tr('من المسار','of the path')}</small>${btn(tr('استكشف مسارك','Explore your path'),'view','journey','primary')}</div><section class="mini-library"><span class="eyebrow">${tr('معرفة لها مصدر','KNOWLEDGE WITH A SOURCE')}</span><h3>${state.data.sources.filter(s=>s.status==='approved').length} ${tr('مرجعًا في مكتبتك','references in your library')}</h3><p>${tr('كل مقتطف مرتبط بكتابه وصفحته، وردود المختصين المعتمدة تثري المعرفة.','Every excerpt links to its book and page. Reviewed specialist answers enrich the library.')}</p><div class="subject-tags"><span>${subject('tawhid')}</span><span>${subject('fiqh')}</span><span>${subject('hadith')}</span><span>${subject('sirah')}</span></div></section></aside></div>`;
}
const bookLanguage=code=>code==='tl'?'fil':code;
const bookLanguageName=code=>LANGUAGE_NAMES[bookLanguage(code)]||code?.toUpperCase()||'';
function journeySources(){return (state.data?.sources||[]).filter(s=>s.status==='approved'&&(!state.journeyLanguage||state.journeyLanguage==='all'||bookLanguage(s.language)===state.journeyLanguage));}
function journeyLesson(s){return `<article class="lesson" data-source-id="${esc(s.id)}"><div class="lesson-heading">${icon('book')}<h3>${subject(s.subject)}</h3>${state.data.completed.includes(s.id)?'<span class="done" aria-label="'+tr('أتممت القراءة','Mark completed')+'">'+icon('check')+'</span>':''}</div><p class="lesson-title" dir="auto">${esc(s.title)}</p><div class="lesson-meta"><span class="pill" dir="auto">${esc(bookLanguageName(s.language))}</span>${s.uploaded_by?`<small>${tr('رفعه','Uploaded by')}: <bdi>${esc(s.uploaded_by)}</bdi></small>`:''}</div><div class="lesson-actions"><a class="secondary" href="/api/sources/${encodeURIComponent(s.id)}/file" target="_blank" rel="noopener">${tr('قراءة الكتاب','Read book')}</a>${btn(tr('اسأل عنه','Ask about it'),'ask',tr('أريد التعرف على','Tell me about')+' '+subject(s.subject),'quiet')}${!state.data.completed.includes(s.id)?btn(tr('أتممت القراءة','Mark completed'),'complete',s.id,'text-link'):''}</div></article>`;}
function journeyPage(){
  const approved=(state.data.sources||[]).filter(s=>s.status==='approved');
  const languages=[...new Set([...Object.keys(LANGUAGE_NAMES),...approved.map(s=>bookLanguage(s.language))])];
  if(state.journeyLanguage&&!languages.includes(state.journeyLanguage)&&state.journeyLanguage!=='all')state.journeyLanguage='all';
  const sources=journeySources(),general=sources.filter(s=>![1,2,3].includes(Number(s.level)));
  return title('رحلتك، خطوة بخطوة','Your journey, step by step',tr('اختر كتابًا من مستواك، واقرأ أو اسأل المساعد عنه.','Choose a book for your level, then read or ask the assistant.'))+`<section class="panel journey-toolbar"><div><h2>${tr('كتب مسارك ومكتبتك','Your learning library')}</h2><p class="muted">${tr('كل الكتب المعتمدة متاحة هنا. اختر لغة الكتب دون تغيير لغة الواجهة.','All approved books are available here. Filter book language without changing the interface language.')}</p><p id="journey-count" class="muted" role="status" aria-live="polite">${sources.length} / ${approved.length} ${tr('كتابًا','books')}</p></div><label for="journey-language">${tr('لغة الكتب','Book language')}<select id="journey-language" aria-controls="journey-books"><option value="all">${tr('كل اللغات','All languages')}</option>${languages.map(code=>`<option value="${esc(code)}" ${state.journeyLanguage===code?'selected':''}>${esc(bookLanguageName(code))}</option>`).join('')}</select></label></section><div id="journey-books">${sources.length?`<div class="level-grid">${[1,2,3].map(level=>`<section class="level-card"><span class="level-number">0${level}</span><h2>${tr('المستوى','Level')} ${level}</h2>${sources.filter(s=>Number(s.level)===level).map(journeyLesson).join('')||`<p class="muted">${tr('لا توجد كتب في هذا المستوى باللغة المختارة.','No books at this level in the selected language.')}</p>`}</section>`).join('')}</div>${general.length?`<section class="panel journey-general"><h2>${tr('مراجع عامة وكتب إضافية','General references and additional books')}</h2><div class="journey-general-grid">${general.map(journeyLesson).join('')}</div></section>`:''}`:`<div class="empty"><h2>${tr('لا توجد كتب معتمدة باللغة المختارة بعد.','No approved books in the selected language yet.')}</h2>${btn(tr('عرض كل الكتب','Show all books'),'journey-all','','secondary')}</div>`}</div>`;
}
function renderWebIdentity(){
  const target=$('#web-user');if(!target)return;
  target.hidden=!state.user;
  target.innerHTML=state.user?`<span class="web-user-avatar" aria-hidden="true">${esc(Array.from(state.user.display_name||state.user.username||'')[0]||'')}</span><span class="web-user-copy"><small>${tr('أهلًا بك','Welcome')}</small><strong dir="auto">${esc(state.user.display_name||state.user.username)}</strong><small>${accountRoleText(state.user.role)}${state.user.office?.name?' · <bdi>'+esc(state.user.office.name)+'</bdi>':''}</small></span>`:'';
}
const faqGroups=()=>[[tr('بدايتي','Getting started'),[tr('ما معنى الإسلام؟','What is Islam?'),tr('ما أركان الإسلام؟','What are the pillars of Islam?'),tr('ما معنى التوحيد؟','What is tawhid?')]],[tr('عبادتي','My worship'),[tr('كيف أتعلم الوضوء؟','How do I perform wudu?'),tr('ما أركان الصلاة؟','What are the pillars of prayer?'),tr('ما معنى الصيام؟','What is fasting?')]],[tr('حياتي اليومية','Daily life'),[tr('ما فضل حسن الخلق؟','What is the value of good character?'),tr('حدثني عن الصدق','Tell me about honesty'),tr('كيف أطلب مساعدة المختص؟','How can I ask a specialist?')]]];
function faqPage(){return title('أسئلتك، بداية المعرفة','Questions open the door to learning')+`<div class="faq-grid">${faqGroups().map(([title,questions])=>`<section class="panel"><h2>${title}</h2>${questions.map(q=>btn(esc(q)+' <span>↗</span>','ask',q,'faq-question')).join('')}</section>`).join('')}</div>`;}
function userTickets(){return title('معك حتى تصل الإجابة','Support until you get an answer',tr('تُحفظ تذاكرك وردود المختص في هذه الزيارة والزيارات التالية.','Your tickets and specialist replies remain available across visits.'))+`<div class="ticket-list">${state.data.tickets.length?state.data.tickets.map(ticket=>`<article class="panel"><div class="row"><span class="pill">#${ticket.id}</span><span class="pill ${ticket.status==='answered'?'success':'amber'}">${ticket.status==='answered'?tr('تمت الإجابة','Answered'):tr('بانتظار المختص','Awaiting specialist')}</span><small>${date(ticket.created_at)}</small></div><h3>${esc(ticket.question)}</h3>${ticket.specialist_response?`<p class="message-text">${esc(ticket.specialist_response)}</p><small>${esc(ticket.assigned_to)}</small>`:`<p class="muted">${tr('وصل طلبك إلى الإدارة. سيظهر الرد هنا وفي المحادثة.','Your request reached the office. The reply will appear here and in chat.')}</p>`}</article>`).join(''):`<div class="empty">${icon('chat')}<h2>${tr('ليس لديك تذاكر بعد','No tickets yet')}</h2><p>${tr('يمكنك طلب المختص من أي إجابة أو فتح تذكرة مباشرة.','Ask for a specialist from any answer, or open a ticket.')}</p>${btn(tr('فتح تذكرة','Open a ticket'),'new-ticket','','primary')}</div>`}</div>`;}

function adminNav(){const entries=[['overview',tr('نظرة عامة','Overview')],['tickets',tr('استفسارات المهتدين','Learner inquiries')],['library',tr('المكتبة والمراجع','Library')],['quality',tr('فحص الجودة والتعلّم','Quality & learning')]];if(can('settings'))entries.push(['settings',tr('الذكاء الاصطناعي والصوت','AI & voice')]);if(['users','offices','admins'].some(can))entries.push(['accounts',tr('الحسابات والمكاتب','Accounts & offices')]);if(state.user?.office_owner)entries.push(['staff',tr('فريق المكتب','Office staff')]);return `<nav class="office-tabs">${entries.filter(([key])=>state.user.role==='office'||['overview','accounts'].includes(key)||can(key)).map(([key,label])=>btn(label,'admin-tab',key,state.adminTab===key?'subnav-active':'subnav-btn')).join('')}</nav>`;}
function overview(){const data=state.office;return `<div class="stat-grid">${[[data.learners.length,tr('مستفيدون في المتابعة','Learners followed')],[data.tickets.filter(t=>t.status==='open').length,tr('تذاكر تنتظر الرد','Awaiting a reply')],[data.sources.filter(s=>s.status==='approved').length,tr('مراجع معتمدة','Approved references')],[data.corrections.filter(c=>c.status==='approved').length,tr('إجابات متعلّمة ومعتمدة','Reviewed learned answers')]].map(([n,l])=>`<article class="stat"><span>${l}</span><strong>${n}</strong></article>`).join('')}</div><section class="panel"><div class="section-heading"><h2>${tr('متابعة رحلة المستفيد','Learner journey follow-up')}</h2><span class="pill">${tr('مساحة عمل بصلاحيات','Access-controlled workspace')}</span></div><div class="table-wrap"><table><thead><tr>${[tr('المستفيد','Learner'),tr('اللغة','Language'),tr('المرحلة','Stage'),tr('التقدم','Progress'),tr('آخر تفاعل','Last activity')].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${data.learners.map(l=>`<tr><td>${esc(l.display_name)}</td><td>${l.language.toUpperCase()}</td><td>${esc(l.learning_stage)}</td><td><div class="table-progress">${l.progress}%<i><em style="width:${l.progress}%"></em></i></div></td><td>${date(l.last_active_at)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>${tr('آخر عمليات المراجعة','Recent review activity')}</h2><div class="audit-list">${data.audit.slice(0,6).map(a=>`<div><span>${esc(({reference_added:tr('إضافة مرجع','Reference added'),reference_indexed:tr('فهرسة مرجع','Reference indexed'),correction_approved:tr('اعتماد تصحيح','Correction approved'),specialist_replied:tr('رد مختص','Specialist replied'),ticket_opened:tr('فتح تذكرة','Ticket opened')})[a.action]||a.action)}</span><small>${date(a.created_at)}</small></div>`).join('')||tr('لا توجد عمليات بعد.','No activity yet.')}</div></section>`;}
function officeTickets(){return `<div class="section-heading"><div><h2>${tr('كل سؤال يصل إلى من يساعد','Every question reaches someone who can help')}</h2><p class="muted">${tr('يمكن ترشيح الردود العامة للتعلّم. تُراجع قبل إعادة استخدامها، ولا تُعمّم الفتاوى الخاصة.','General replies can be proposed for learning. Review is required before reuse; personal rulings are not generalized.')}</p></div></div><div class="ticket-list">${state.office.tickets.map(t=>`<article class="panel ticket-card"><div class="row"><span class="pill">#${t.id}</span><strong>${esc(t.learner_name)}</strong><span class="pill ${t.status==='answered'?'success':'amber'}">${t.status==='answered'?tr('تمت الإجابة','Answered'):tr('جديدة','Open')}</span></div><h3>${esc(t.question)}</h3><p class="muted">${esc(t.reason)} · ${t.language.toUpperCase()}</p><details><summary>${tr('عرض سياق المحادثة','View conversation context')}</summary><pre class="context">${esc(formatContext(t.source_context))}</pre></details>${t.specialist_response?`<div class="reviewed-reply"><p>${esc(t.specialist_response)}</p><small>${esc(t.assigned_to)}</small></div>`:`<form class="reply-form" data-ticket="${t.id}"><label>${tr('رد المختص','Specialist answer')}<textarea name="response" required rows="4" maxlength="12000"></textarea></label><div class="form-grid"><label>${tr('اسم المختص','Specialist name')}<input name="reviewer" required></label><label>${tr('توثيق الإجابة','Answer source')}<input name="source_note" placeholder="${tr('الكتاب والصفحة، أو مرجع الرد','Book and page, or answer reference')}"></label></div><label class="checkbox"><input type="checkbox" name="learn">${tr('ترشيح هذه الإجابة العامة للتعلّم بعد المراجعة','Propose this general answer for learning after review')}</label><button class="primary" type="submit">${tr('إرسال الرد للمستفيد','Send answer to learner')}</button></form>`}</article>`).join('')||`<div class="empty">${tr('لا توجد استفسارات حتى الآن.','No inquiries yet.')}</div>`}</div>`;}
function formatContext(value){try{const rows=JSON.parse(value||'[]');return Array.isArray(rows)?rows.map(r=>`${r.role==='user'?'المستفيد':'المساعد'}: ${r.content}`).join('\n\n'):value;}catch{return value||'';}}
function libraryPage(){const sources=state.office.sources;return `<section class="panel"><div class="section-heading"><div><h2>${tr('إضافة مرجع إلى المكتبة','Add a library reference')}</h2><p class="muted">${tr('يُستخرج النص أولًا؛ تراجع المرجع وتقرّه قبل استخدامه في الإجابات.','Text is extracted first. Review and approve the source before it is used in answers.')}</p></div><span class="pill">PDF · 80 MB</span></div><form id="upload-form" class="upload-form"><div class="form-grid"><label>${tr('ملف المرجع','Reference file')}<input type="file" name="file" accept="application/pdf" required></label><label>${tr('لغة المرجع','Source language')}<select name="language"><option value="ar">العربية</option><option value="en">English</option><option value="fil">Filipino</option><option value="fr">Français</option><option value="am">አማርኛ</option><option value="sw">Kiswahili</option><option value="ur">اردو</option><option value="tl">Filipino</option></select></label><label>${tr('المستوى','Level')}<select name="level"><option value="0">${tr('عام','General')}</option>${[1,2,3].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label><label>${tr('التصنيف','Subject')}<select name="subject">${['general','tawhid','fiqh','hadith','sirah'].map(k=>`<option value="${k}">${subject(k)}</option>`).join('')}</select></label></div><button class="primary" type="submit">${tr('رفع المرجع ومعالجته','Upload and process')}</button><span id="upload-status" class="muted" role="status"></span></form></section><div class="library-summary"><strong>${sources.length} ${tr('مرجعًا','references')}</strong><span>${state.office.stats.passages} ${tr('مقطعًا مفهرسًا','indexed passages')}</span><span>${state.office.stats.review_pages} ${tr('صفحة تحتاج مراجعة','pages need review')}</span>${btn(tr('تحديث الحالة','Refresh status'),'refresh')}</div><div class="books-grid">${sources.map(s=>`<article class="book-card"><div class="book-icon">${icon('book')}</div><div class="row"><span class="pill">${s.language.toUpperCase()}</span>${s.level?`<span class="pill">${tr('المستوى','Level')} ${s.level}</span>`:''}<span class="pill ${s.status==='approved'?'success':'amber'}">${s.status==='approved'?tr('معتمد','Approved'):tr('للمراجعة','Pending review')}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.collection)} · ${subject(s.subject)}</p><small>${s.page_count} ${tr('صفحة','pages')} · ${s.passage_count} ${tr('مقطعًا','passages')}</small><small class="process-state">${esc(({ready:tr('تمت الفهرسة','Indexed'),queued:tr('في قائمة المعالجة','Queued'),indexing:tr('جارٍ استخراج النص','Extracting text'),needs_review:tr('بعض الصفحات تحتاج OCR أو مراجعة','Some pages need OCR or review'),failed:tr('تعذرت المعالجة','Processing failed')})[s.processing_status]||s.processing_status)}</small><div class="book-actions"><a class="text-link" href="/api/sources/${s.id}/file" target="_blank" rel="noopener">${tr('فتح الأصل','Open original')}</a>${s.status!=='approved'?btn(tr('اعتماد المرجع','Approve source'),'approve-source',s.id):''}</div></article>`).join('')}</div>`;}
function correctionForm(){const c=state.correction||{};return `<form id="correction-form" class="correction-form"><input type="hidden" name="message_id" value="${esc(c.message_id||'')}"><label>${tr('السؤال المراد تصحيح إجابته','Question to correct')}<input name="question" required value="${esc(c.question||'')}"></label><label>${tr('الإجابة الصحيحة','Correct answer')}<textarea name="answer" required rows="4">${esc(c.answer||'')}</textarea></label><div class="form-grid"><label>${tr('المصدر والصفحة أو توثيق المختص','Source, page, or specialist evidence')}<input name="source_note" required value="${esc(c.source_note||'')}"></label><label>${tr('اسم المراجع','Reviewer name')}<input name="reviewer" required></label><label>${tr('لغة الإجابة','Answer language')}<select name="language"><option value="ar">العربية</option><option value="en">English</option><option value="fil">Filipino</option><option value="fr">Français</option><option value="am">አማርኛ</option><option value="sw">Kiswahili</option></select></label></div><button class="primary" type="submit">${tr('حفظ التصحيح للمراجعة','Save correction for review')}</button></form>`;}
function qualityPage(){return `<section class="panel"><h2>${tr('ابحث وتحقق من الإجابة','Search and verify an answer')}</h2><p class="muted">${tr('افحص نصوص المكتبة أو جرّب جواب المساعد. التجربة هنا لا تفتح تذكرة ولا تُرسل إلى المستفيد.','Inspect library passages or test an assistant answer. This does not open tickets or send anything to a learner.')}</p><form id="search-form" class="search-form"><label class="grow">${tr('السؤال أو كلمات البحث','Question or search terms')}<input name="q" required value="${esc(state.searchQuery)}" placeholder="${tr('مثل: ما معنى التوحيد؟','For example: What is tawhid?')}"></label><label>${tr('المرجع','Reference')}<select name="source_id"><option value="">${tr('كل المراجع','All references')}</option>${state.office.sources.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')}</select></label><label>${tr('المستوى','Level')}<select name="level"><option value="">${tr('الكل','All')}</option><option>1</option><option>2</option><option>3</option></select></label><button class="primary" name="mode" value="search" type="submit">${icon('search')}${tr('بحث في المصادر','Search sources')}</button><button class="secondary" name="mode" value="evaluate" type="submit">${tr('اختبار المساعد','Test assistant')}</button></form>${state.evaluation?`<div class="test-answer"><span class="pill">${modeLabel(state.evaluation.mode)}</span><p class="message-text">${esc(state.evaluation.content)}</p>${citations(state.evaluation.citations)}${btn(tr('تصحيح هذا الجواب','Correct this answer'),'correct-test')}</div>`:''}<div class="search-results">${state.search.map(r=>`<article><div class="row"><span class="pill">${subject(r.subject)}</span><span class="pill">${tr('تطابق','Match')} ${Math.round(r.coverage*100)}%</span></div>${citations([r])}<p class="message-text">${esc(r.content)}</p></article>`).join('')}</div></section><div class="quality-grid"><section class="panel" id="correct-panel"><h2>${tr('تصحيح يُثري معرفة المساعد','A correction that improves the assistant')}</h2><p class="muted">${tr('التعلّم هنا بإضافة إجابات موثقة ومعتمدة إلى قاعدة المعرفة؛ وليس تدريبًا تلقائيًا لأوزان النموذج.','Learning adds documented, reviewed answers to the knowledge base. It does not automatically train model weights.')}</p>${correctionForm()}</section><section class="panel"><h2>${tr('قائمة المراجعة','Review queue')}</h2>${state.office.corrections.map(c=>`<article class="correction-item"><div class="row"><span class="pill ${c.status==='approved'?'success':'amber'}">${({pending:tr('بانتظار المراجعة','Pending'),approved:tr('معتمد للتعلّم','Approved for reuse'),rejected:tr('مستبعد','Rejected')})[c.status]}</span><small>${c.origin_ticket_id?tr('من تذكرة','From ticket')+' #'+c.origin_ticket_id:tr('تصحيح المكتب','Office correction')}</small></div><h3>${esc(c.question)}</h3><p>${esc(c.answer)}</p><small>${esc(c.source_note)} · ${esc(c.reviewer)}</small><div class="row">${c.status!=='approved'?btn(tr('اعتماد للتعلّم','Approve for learning'),'approve-correction',c.id):btn(tr('إيقاف استخدام التصحيح','Revoke approval'),'revoke-correction',c.id,'quiet')}</div></article>`).join('')||`<p class="empty-inline">${tr('تظهر هنا تصحيحات المكتب وردود المختصين المرشحة للتعلّم.','Office corrections and specialist answers proposed for learning appear here.')}</p>`}</section></div><section class="panel"><h2>${tr('سجل مخرجات المساعد','Assistant answer history')}</h2>${state.office.answers.slice(0,20).map(m=>`<details class="answer-log"><summary>${esc(m.question)} <span class="pill">${modeLabel(m.mode)}</span></summary><p class="message-text">${esc(m.content)}</p>${citations(m.citations)}${btn(tr('اقتراح تصحيح','Propose correction'),'correct-message',m.id)}</details>`).join('')||`<p class="muted">${tr('لا توجد إجابات مسجلة بعد.','No answers recorded yet.')}</p>`}</section>`;}
function settingsPage(){const a=state.office.ai;return `<section class="panel settings-panel"><span class="pill ${a.configured?'success':'amber'}">${a.configured?tr('المفتاح محفوظ — اختبر الاتصال','Key saved — test the connection'):tr('بانتظار مفتاح الخدمة','Awaiting service key')}</span><h2>${tr('تفعيل المساعد والصوت المحسّن','Activate AI and enhanced voice')}</h2><p>${tr('أدخل مفتاح OpenAI الخاص بالمشروع. سيُرسل السؤال والمقاطع اللازمة والتسجيل الصوتي عند استخدامه إلى الخدمة. يبقى المفتاح في ملف .enviroment.local داخل الخادم، وهو مستثنى من Git ولا يُرسل للمستفيد.','The key stays in the server-only .enviroment.local file and is excluded from Git. Questions, relevant excerpts and submitted audio are sent to OpenAI when used.')}</p><form id="settings-form"><label>${tr('مفتاح الخدمة','API key')}<input name="api_key" type="password" autocomplete="new-password" placeholder="${a.configured?tr('اتركه فارغًا للاحتفاظ بالمفتاح','Leave empty to keep the key'):'sk-…'}"></label><div class="form-grid"><label>${tr('نموذج الإجابات','Answer model')}<input name="model" value="${esc(a.model)}"></label><label>${tr('نموذج القراءة','Speech model')}<input name="tts_model" value="${esc(a.tts_model)}"></label><label>${tr('نموذج تفريغ السؤال','Transcription model')}<input name="transcribe_model" value="${esc(a.transcribe_model)}"></label><label>${tr('الصوت','Voice')}<select name="voice">${['coral','marin','cedar','alloy','nova'].map(v=>`<option ${a.voice===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="row"><button class="primary" type="submit">${tr('حفظ الإعدادات','Save settings')}</button>${btn(tr('اختبار اتصال الذكاء الاصطناعي','Test AI connection'),'test-ai')}${btn(tr('تجربة الصوت العربي','Test Arabic voice'),'test-voice')}</div><p class="muted">${tr('استخدام الخدمة يُحاسب على حساب المشروع. الصوت الناتج مولّد بالذكاء الاصطناعي، وليس تسجيلًا بشريًا أو تلاوة معتمدة.','API usage is billed to the project account. Audio is AI-generated, not a human recording or an authenticated recitation.')}</p><div id="settings-audio"></div></form></section>`;}
function canReviewSource(source){return !!source&&(can('library')||(state.user?.role==='office'&&source.status==='pending_review'&&source.uploaded_by_office_id===state.user.office_id));}
function sourceReviewHint(source){
  if(['queued','indexing'].includes(source.processing_status))return tr('الفهرسة جارية؛ حدّث الحالة عند اكتمالها.','Indexing is running; refresh when it finishes.');
  if(source.processing_status==='failed')return tr('تعذرت الفهرسة؛ أعد المحاولة أو راجع النص يدويًا.','Indexing failed; retry or review the text manually.');
  if(!source.passage_count)return tr('لا يوجد نص صالح للإجابات بعد. راجع النص من الأصل واحفظه أولًا.','No usable answer text yet. Review and save the text from the original first.');
  return '';
}
function sourceReviewActions(source){
  const editable=canReviewSource(source),waiting=['queued','indexing','failed'].includes(source.processing_status);
  return `${editable?btn(tr('مراجعة النص','Review text'),'review-source',source.id):''}${source.status!=='approved'&&can('library')&&source.passage_count>0&&!waiting?btn(tr('اعتماد المرجع','Approve source'),'approve-source',source.id):''}`;
}
function decorateSourceReview(){
  document.querySelectorAll('.book-card').forEach(card=>{
    const original=card.querySelector('a[href^="/api/sources/"]');
    const sid=original?.getAttribute('href')?.match(/^\/api\/sources\/([^/]+)\/file$/)?.[1];
    const source=state.office?.sources.find(s=>s.id===sid);if(!source)return;
    card.querySelector('[data-action="approve-source"]')?.remove();
    const hint=sourceReviewHint(source);
    if(hint){const note=document.createElement('p');note.className='source-review-hint';note.textContent=hint;card.querySelector('.book-actions').before(note);}
    card.querySelector('.book-actions').insertAdjacentHTML('beforeend',sourceReviewActions(source));
  });
}
async function openSourceReview(sid,pageNumber){
  const data=await api('/api/sources/'+encodeURIComponent(sid)+'/pages');
  const page=pageNumber?data.pages.find(p=>p.page_number===Number(pageNumber)):(data.pages.find(p=>['needs_ocr','needs_review','sparse'].includes(p.extraction_status))||data.pages[0]);
  if(!page)throw new Error(tr('الصفحة غير موجودة أو لم تنته المعالجة.','Page not found or processing is incomplete.'));
  state.reviewSource=sid;state.reviewPage=page;render();
  $('#page-review-panel')?.scrollIntoView({behavior:'smooth',block:'start'});
  $('#page-review-panel')?.focus({preventScroll:true});
}
function pageReviewPanel(){
  const source=state.office.sources.find(s=>s.id===state.reviewSource),editable=canReviewSource(source);
  return `<section class="panel" id="page-review-panel" tabindex="-1"><h2>${tr('مراجعة النص المستخرج من الصفحات','Review extracted page text')}</h2><p class="muted">${tr('افتح الصفحة الأصلية وقارنها بالنص. يحفظ التصحيح في المكتبة مع اسم المراجع ويعاد فهرسته فورًا.','Compare the original page with its text. A reviewed correction is saved with reviewer attribution and immediately reindexed.')}</p><form id="page-lookup" class="search-form"><label class="grow">${tr('الكتاب','Book')}<select name="source_id">${state.office.sources.map(s=>`<option value="${esc(s.id)}" ${state.reviewSource===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label>${tr('رقم الصفحة في الملف','PDF page number')}<input type="number" min="1" name="page" value="${state.reviewPage?.page_number||1}" required></label><button class="secondary" type="submit">${tr('عرض النص للمراجعة','Load page text')}</button></form>${state.reviewPage&&source?`<h3 dir="auto">${esc(source.title)}</h3>${sourceReviewHint(source)?`<p class="source-review-hint">${sourceReviewHint(source)}</p>`:''}<form id="page-review-form" class="correction-form"><div class="row"><a href="/api/sources/${encodeURIComponent(source.id)}/file#page=${state.reviewPage.page_number}" target="_blank" rel="noopener" class="text-link">${tr('فتح الصفحة الأصلية','Open original page')}</a><span class="pill">${esc(state.reviewPage.extraction_status)}</span></div><label>${tr('النص بعد المراجعة','Reviewed text')}<textarea name="text" rows="10" minlength="35" maxlength="30000" dir="auto" required ${editable?'':'readonly'}>${esc(state.reviewPage.raw_text)}</textarea></label>${editable?`<label>${tr('اسم المراجع','Reviewer name')}<input name="reviewer" value="${esc(state.user.display_name)}" readonly required></label><label class="checkbox"><input type="checkbox" name="verified" required>${tr('قارنت النص بالصفحة الأصلية وأؤكد صحته بلغته.','I compared this text with the original page and confirm its accuracy in its language.')}</label><button class="primary" type="submit">${tr('حفظ النص المراجع وإعادة فهرسته','Save reviewed text and reindex')}</button>`:''}</form>${can('library')&&source.status!=='approved'&&source.passage_count>0&&!['queued','indexing','failed'].includes(source.processing_status)?`<div class="review-approve"><p>${tr('النص المفهرس متاح. اعتماد المرجع خطوة مستقلة بعد المراجعة.','Indexed text is available. Approve the source separately after review.')}</p>${btn(tr('اعتماد المرجع','Approve source'),'approve-source',source.id,'primary')}</div>`:''}`:''}</section>`;
}
function adminPage(){if(!adminTabAllowed(state.adminTab))state.adminTab='overview';if(!state.office)return '<p class="loading">…</p>';return title(state.user.role==='admin'?'الإدارة المركزية':'بوابة مكتب الدعوة والإرشاد',state.user.role==='admin'?'Central administration':'Dawah & guidance office',tr('متابعة المستفيدين، رعاية أسئلتهم، وتحسين المعرفة.','Follow learners, support their questions, and improve the knowledge base.'))+adminNav()+({overview,tickets:officeTickets,library:()=>libraryPage()+libraryControls()+pageReviewPanel(),quality:qualityPage,settings:()=>settingsPage()+registrationPage(),accounts:accountsPage,staff:staffPage}[state.adminTab]||overview)();}
function render(){
  document.documentElement.lang=state.language;document.documentElement.dir=state.language==='ar'?'rtl':'ltr';
  renderWebIdentity();
  const preview=$('#try-app');if(preview){const label=({ar:'تجربة التطبيق',en:'Try the app',fil:'Subukan ang app',fr:'Essayer l’application',am:'መተግበሪያውን ይሞክሩ',sw:'Jaribu programu'})[state.language];preview.querySelector('span').textContent=label;preview.setAttribute('aria-label',label);}
  $('#language-toggle').value=state.language;$('#brand-sub').textContent=tr('معك، خطوة بخطوة','With you, step by step');$('#learner-nav').textContent=tr('رحلتي','My journey');$('#office-nav').textContent=state.user?.role==='admin'?tr('الإدارة المركزية','Central administration'):tr('بوابة المكتب','Office portal');
  $('#profile-nav').textContent=tr('حسابي','My account');$('#logout-nav').textContent=tr('خروج','Sign out');$('#logout-nav').hidden=!state.user;$('#profile-nav').hidden=!state.user;$('#office-nav').hidden=!accountReady()||state.user.role==='member';$('#learner-nav').hidden=!accountReady();
  if(!state.user){$('#app').innerHTML=authPage();bindAccountForms();return;}
  if(state.view==='profile'||!accountReady()){$('#app').innerHTML=profilePage();bindAccountForms();return;}
  if(!state.data)return;
  $('#learner-nav').classList.toggle('active',state.view!=='admin');$('#office-nav').classList.toggle('active',state.view==='admin');
  $('#app').innerHTML=(state.view==='admin'?'':learnerNav())+({chat:chatPage,journey:journeyPage,faq:faqPage,tickets:userTickets,admin:adminPage}[state.view]||chatPage)();
  bindForms();
  bindAccountForms();decorateControls();
  if(state.view==='chat'){const log=$('#messages');log.scrollTop=log.scrollHeight;}
}
async function switchView(view){if($('#question'))state.draft=$('#question').value;if(state.recorder?.state==='recording')state.recorder.stop();state.recognition?.stop();stopAudio();state.view=view;await load();render();}
async function sendQuestion(question){if(state.busy||!question.trim())return;state.draft=question;state.busy=true;state.view='chat';render();try{const data=await api('/api/ask',{question,language:state.language,office_id:state.ticketOffice||null});state.data.messages=data.messages;state.draft='';await load();}catch(e){toast(e.message);}finally{state.busy=false;render();$('#question')?.focus();}}
function bindForms(){
  if(state.view==='admin'&&state.adminTab==='library')decorateSourceReview();
  $('#journey-language')?.addEventListener('change',e=>{state.journeyLanguage=e.target.value;render();$('#journey-language')?.focus({preventScroll:true});});
  $('#page-lookup')?.addEventListener('submit',e=>formTask(e,async form=>{const f=new FormData(form);await openSourceReview(f.get('source_id'),f.get('page'));}));
  $('#page-review-form')?.addEventListener('submit',e=>formTask(e,async form=>{const sid=state.reviewSource,page=state.reviewPage.page_number;await api('/api/sources/'+sid+'/pages/'+page,Object.fromEntries(new FormData(form)));await load();await openSourceReview(sid,page);toast(tr('حُفظ التصحيح وأُعيدت فهرسة الصفحة.','Page correction saved and reindexed.'));}));
  $('#question')?.addEventListener('input',e=>state.draft=e.target.value);
  $('#question')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#chat-form').requestSubmit();}});
  $('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();sendQuestion($('#question').value);});
  $('#upload-form')?.addEventListener('submit',e=>formTask(e,async form=>{const f=new FormData(form),file=f.get('file');if(file.size>80*1024*1024)throw new Error(tr('الحد الأقصى 80 ميغابايت.','Maximum file size is 80 MB.'));$('#upload-status').textContent=tr('جارٍ الرفع…','Uploading…');await api('/api/sources/upload',undefined,{method:'POST',headers:{'X-Filename':encodeURIComponent(file.name),'X-Language':f.get('language'),'X-Level':f.get('level'),'X-Subject':f.get('subject')},body:file});await load();render();toast(tr('حُفظ المرجع وبدأت المعالجة. حدّث الحالة ثم راجع النص قبل الاعتماد.','Reference saved and processing started. Refresh and review before approval.'));}));
  $('#search-form')?.addEventListener('submit',e=>{const mode=e.submitter?.value;formTask(e,async form=>{const f=new FormData(form);state.searchQuery=f.get('q');if(mode==='evaluate'){state.evaluation=await api('/api/evaluate',{question:f.get('q'),language:state.language});state.search=[];}else{const data=await api('/api/search?'+new URLSearchParams(f));state.search=data.results;state.evaluation=null;if(!data.results.length)toast(tr('لا توجد نتائج مطابقة.','No matching results.'));}render();});});
  $('#correction-form')?.addEventListener('submit',e=>formTask(e,async form=>{await api('/api/corrections',Object.fromEntries(new FormData(form)));state.correction=null;await load();render();toast(tr('حُفظ التصحيح في قائمة المراجعة. اعتمده ليُستخدم في الإجابات.','Correction saved for review. Approve it to enable reuse.'));}));
  document.querySelectorAll('.reply-form').forEach(form=>form.addEventListener('submit',e=>formTask(e,async form=>{const payload=Object.fromEntries(new FormData(form));payload.learn=Boolean(payload.learn);await api('/api/tickets/'+form.dataset.ticket+'/reply',payload);await load();render();toast(tr('وصل الرد إلى محادثة المستفيد.','The reply is now in the learner conversation.'));})));
  $('#settings-form')?.addEventListener('submit',e=>formTask(e,async form=>{await api('/api/settings',Object.fromEntries(new FormData(form)));form.reset();await load();render();toast(tr('حُفظت الإعدادات. استخدم اختبار الاتصال للتحقق.','Settings saved. Test the connection to verify.'));}));
  $('#audio-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(file)try{await transcribe(file);}catch(error){toast(error.message);}});
}
async function formTask(event,run){event.preventDefault();const form=event.currentTarget;const button=event.submitter;if(button)button.disabled=true;try{await run(form);}catch(error){toast(error.message);}finally{if(button?.isConnected)button.disabled=false;}}
function stopAudio(){state.reader?.abort();state.reader=null;if(state.audio){state.audio.pause();state.audio=null;}if(state.audioUrl){URL.revokeObjectURL(state.audioUrl);state.audioUrl=null;}window.speechSynthesis?.cancel();}
function speechText(text){return text.normalize('NFKC').replace(/https?:\/\/\S+/g,'').replace(/ﷺ/g,'صلى الله عليه وسلم').replace(/[#*_`]+/g,'').trim();}
async function localSpeak(text,language){
  if(!('speechSynthesis' in window))throw new Error(tr('الصوت المحلي غير متاح. فعّل الصوت المحسّن من الإدارة.','Local speech is unavailable. Activate enhanced voice in administrator settings.'));
  let voices=speechSynthesis.getVoices();
  if(!voices.length){await new Promise(resolve=>{speechSynthesis.addEventListener('voiceschanged',resolve,{once:true});setTimeout(resolve,1200);});voices=speechSynthesis.getVoices();}
  const voice=voices.find(v=>v.lang.toLowerCase().startsWith(language==='fil'?'fil':language)||language==='fil'&&v.lang.toLowerCase().startsWith('tl'));
  if(!voice)throw new Error(tr('لا يوجد صوت عربي مناسب على الجهاز. فعّل الصوت المحسّن من الإدارة.','No matching language voice is installed. Activate enhanced voice in administrator settings.'));
  const segments=[];let remaining=text;while(remaining.length>180){let cut=remaining.lastIndexOf(' ',180);if(cut<1)cut=180;segments.push(remaining.slice(0,cut));remaining=remaining.slice(cut).trim();}if(remaining)segments.push(remaining);
  state.utterances=segments.map(part=>{const u=new SpeechSynthesisUtterance(part);u.lang=voice.lang;u.voice=voice;u.rate=.88;return u;});
  state.utterances.forEach(u=>speechSynthesis.speak(u));
  toast(tr('قراءة محلية بصوت '+voice.name+'؛ يمكن إيقافها من زر الاستماع.','Local voice: '+voice.name+'. Press Listen again to stop.'));
}
async function speak(text,target,forcedLanguage){
  if(state.audio||window.speechSynthesis?.speaking){stopAudio();return;}
  stopAudio();text=speechText(text);const language=forcedLanguage||state.language;
  if(!state.data.ai.audio_configured)return localSpeak(text,language);
  const parts=[];while(text.length>3600){let cut=text.lastIndexOf(' ',3500);if(cut<1)cut=3500;parts.push(text.slice(0,cut));text=text.slice(cut).trim();}if(text)parts.push(text);
  const controller=new AbortController();state.reader=controller;let index=0;
  if(target)target.textContent=tr('جارٍ إعداد الصوت…','Preparing audio…');
  const next=async()=>{if(controller.signal.aborted||index>=parts.length)return;const response=await fetch('/api/audio/speech',{method:'POST',headers:{'Content-Type':'application/json','X-Rihlati-Client':'web','X-CSRF-Token':state.csrf||''},body:JSON.stringify({text:parts[index++],language}),signal:controller.signal});if(!response.ok){const error=await response.json();throw new Error(error.error);}const blob=await response.blob();if(state.audioUrl)URL.revokeObjectURL(state.audioUrl);state.audioUrl=URL.createObjectURL(blob);const audio=document.createElement('audio');audio.controls=true;audio.src=state.audioUrl;audio.setAttribute('aria-label',tr('صوت مولد بالذكاء الاصطناعي','AI-generated voice'));state.audio=audio;if(target){target.replaceChildren(audio);const note=document.createElement('small');note.textContent=tr('صوت مولّد بالذكاء الاصطناعي','AI-generated voice');target.append(note);}audio.onended=()=>{state.audio=null;next().catch(e=>toast(e.message));};await audio.play().catch(()=>toast(tr('اضغط تشغيل للاستماع.','Press Play to listen.')));};
  try{await next();}catch(error){if(error.name!=='AbortError'){if(target)target.textContent='';throw error;}}
}
async function transcribe(blob){if(!state.data.ai.audio_configured)throw new Error(tr('تفريغ التسجيلات المحسّن يحتاج تفعيل الخدمة من الإدارة.','Enhanced transcription requires activation in administrator settings.'));if(blob.size>20*1024*1024)throw new Error(tr('التسجيل أكبر من 20 ميغابايت.','Recording exceeds 20 MB.'));toast(tr('جارٍ تحويل الصوت إلى نص…','Transcribing your recording…'));const data=await api('/api/audio/transcribe',undefined,{method:'POST',headers:{'Content-Type':blob.type||'audio/mpeg','X-Language':state.language},body:blob});if(!data.text?.trim())throw new Error(tr('لم أتعرف على كلام واضح. حاول مجددًا.','No clear speech detected. Please retry.'));state.draft=data.text;render();$('#question')?.focus();toast(tr('راجع النص ثم أرسل سؤالك.','Review the transcript, then send your question.'));}
async function record(){
  if(state.recording){state.recorder?.stop();state.recognition?.stop();return;}
  stopAudio();
  if(!state.data.ai.audio_configured){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)throw new Error(tr('هذا المتصفح يحتاج تفعيل التفريغ الصوتي من إعدادات المكتب. يمكنك الكتابة الآن.','This browser needs server transcription activated. You can type your question now.'));const r=new Recognition();state.recognition=r;r.lang=({ar:'ar-SA',en:'en-US',fil:'fil-PH',fr:'fr-FR',am:'am-ET',sw:'sw-KE'})[state.language];r.interimResults=false;r.onresult=e=>{state.draft=e.results[0][0].transcript;render();};r.onerror=e=>toast(tr('تعذر الإملاء المحلي. جرّب الكتابة أو فعّل الصوت المحسّن.','Local dictation failed. Type your question or activate enhanced voice.'));r.onend=()=>{state.recording=false;render();};r.start();state.recording=true;render();return;}
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error(tr('التسجيل غير متاح هنا. استخدم رفع تسجيل صوتي.','Recording is unavailable here. Upload an audio recording instead.'));
  let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});}catch{throw new Error(tr('تعذر الوصول للميكروفون. اسمح به من إعدادات المتصفح أو ارفع تسجيلًا.','Microphone access failed. Allow it in browser settings or upload a recording.'));}
  state.recordStream=stream;const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(type=>MediaRecorder.isTypeSupported(type));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});state.recorder=recorder;const chunks=[];let timer;
  recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=()=>{clearTimeout(timer);stream.getTracks().forEach(t=>t.stop());state.recording=false;render();toast(tr('تعذر إكمال التسجيل.','Recording failed.'));};recorder.onstop=async()=>{clearTimeout(timer);stream.getTracks().forEach(t=>t.stop());state.recording=false;render();try{await transcribe(new Blob(chunks,{type:recorder.mimeType}));}catch(e){toast(e.message);}};
  recorder.start();state.recording=true;render();timer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},60000);
}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,value=button.dataset.value;try{
  if(action==='view')await switchView(value);
  if(action==='admin-tab'){state.adminTab=value;await load();render();}
  if(action==='ask')await sendQuestion(value);
  if(action==='refresh'){await load();render();}
  if(action==='complete'){await api('/api/lessons/complete',{source_id:value});await load();render();toast(tr('أحسنت، حُفظ تقدمك.','Well done. Your progress is saved.'));}
  if(action==='escalate'){await api('/api/tickets',{message_id:Number(value),office_id:state.ticketOffice||null,language:state.language});await load();render();toast(tr('فُتحت تذكرة بسؤالك الأصلي وسياق الإجابة.','Ticket opened with your original question and answer context.'));}
  if(action==='new-ticket'){const question=window.prompt(tr('ما السؤال الذي تريد إرساله للمختص؟','What would you like to ask the specialist?'));if(question?.trim()){await api('/api/tickets',{question,office_id:state.ticketOffice||null,language:state.language});state.view='tickets';await load();render();}}
  if(action==='speak'){const message=state.data.messages.find(m=>String(m.id)===value);if(message)await speak(message.content,document.querySelector(`[data-audio-id="${value}"]`),message.language);}
  if(action==='record')await record();
  if(action==='audio-file')$('#audio-file').click();
  if(action==='journey-all'){state.journeyLanguage='all';render();$('#journey-language')?.focus();}
  if(action==='review-source')await openSourceReview(value);
  if(action==='approve-source'){button.disabled=true;try{await api('/api/sources/'+value+'/approve',{});await load();render();toast(tr('تم اعتماد المرجع وإتاحته في المكتبة.','Source approved and available in the library.'));}catch(error){if(error.code==='source_requires_review'&&error.reviewPage)await openSourceReview(value,error.reviewPage);throw error;}}
  if(action==='approve-correction'||action==='revoke-correction'){await api('/api/corrections/'+value+'/status',{status:action==='approve-correction'?'approved':'pending'});await load();render();}
  if(action==='correct-message'){const message=state.office.answers.find(m=>String(m.id)===value);state.correction={question:message.question,message_id:message.id};render();$('#correct-panel').scrollIntoView({behavior:'smooth'});}
  if(action==='correct-test'){state.correction={question:state.searchQuery};render();$('#correct-panel').scrollIntoView({behavior:'smooth'});}
  if(action==='test-ai'){button.disabled=true;const data=await api('/api/settings/test',{});toast(data.ok?tr('نجح اتصال النموذج وإنتاج جواب الاختبار.','The model connection and test response succeeded.'):tr('لم ينجح الاختبار.','Test failed.'));}
  if(action==='test-voice')await speak('أهلًا بك في رِحلتي. نتعلّم معًا خطوة بخطوة، ويمكنك سؤال المختص متى احتجت.',$('#settings-audio'),'ar');
}catch(error){toast(error.message);}finally{if(button.isConnected)button.disabled=false;}});
$('#language-toggle').addEventListener('change',e=>{if($('#question'))state.draft=$('#question').value;state.language=e.target.value;localStorage.setItem('rihlati-language',state.language);render();});
document.addEventListener('visibilitychange',async()=>{if(accountReady()&&!document.hidden&&!state.busy&&!state.recording){try{const previous=state.data?.messages?.length;state.data=await api('/api/bootstrap');if(state.view==='chat'&&previous!==state.data.messages.length)render();}catch{}}});
setInterval(async()=>{if(document.hidden||state.busy||state.recording||state.audio||!state.data||!['chat','tickets'].includes(state.view))return;try{const previous=state.data.messages.length;const data=await api('/api/bootstrap');if(data.messages.length!==previous||JSON.stringify(data.tickets)!==JSON.stringify(state.data.tickets)){state.data=data;render();}}catch{}},12000);
window.addEventListener('beforeunload',()=>{state.recordStream?.getTracks().forEach(track=>track.stop());stopAudio();});
load().then(()=>render()).catch(error=>{$('#app').innerHTML=`<div class="empty"><h1>${tr('تعذر فتح رِحلتي','Could not open Rihlati')}</h1><p>${esc(error.message)}</p>${btn(tr('إعادة المحاولة','Retry'),'refresh')}</div>`;});
